const announcementDialog=document.getElementById('announcement-dialog');
let announcementFocus=null,announcementRequest=0;
async function openAnnouncement(){
 if(announcementDialog.open)return;
 const request=++announcementRequest;
 announcementFocus=document.activeElement;
 announcementDialog.showModal();
 document.getElementById('close-announcement').focus();
 const content=document.getElementById('announcement-content');
 content.scrollTop=0;
 content.textContent=PinballI18n.t('announcement.loading');
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);
 try{
  const response=await fetch('https://chickeneren43.github.io/document/pinballtales/announcement.html',{cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer',signal:controller.signal});
  if(!response.ok)throw Error('Announcement unavailable');
  const page=new DOMParser().parseFromString(await response.text(),'text/html');
  const section=[...page.querySelectorAll('[data-lang]')].find(node=>node.dataset.lang===PinballI18n.locale)||page.querySelector('[data-lang="en"]');
  if(!section)throw Error('Missing announcement');
  const nodes=[];
  for(const source of section.children){
   if(!['P','H2','A'].includes(source.tagName))continue;
   const node=document.createElement(source.tagName.toLowerCase());node.textContent=source.textContent;
   if(source.tagName==='A'){
    const url=new URL(source.getAttribute('href'),response.url);
    if(url.protocol!=='https:')continue;
    node.href=url.href;node.target='_blank';node.rel='noopener noreferrer';
    if(window.PinballPlatform==='android')node.onclick=event=>{event.preventDefault();location.href=url.href;};
   }
   nodes.push(node);
  }
  if(!nodes.length)throw Error('Empty announcement');
  if(request===announcementRequest)content.replaceChildren(...nodes);
 }catch{if(request===announcementRequest)content.textContent=PinballI18n.t('announcement.offline');}
 finally{clearTimeout(timeout);}
}
