  try{const saved=Number(localStorage.getItem('pinball-volume'));return {language:PinballI18n.locale,sound:hasSystemVolume()?(!Number.isFinite(window.PinballSystemVolume)||window.PinballSystemVolume>0):localStorage.getItem('pinball-sound')!=='off',volume:hasSystemVolume()?1:localStorage.getItem('pinball-volume')===null?1:Math.max(0,Math.min(1,Number.isFinite(saved)?saved:1)),playAspect:'portrait',physicsModel:'legacy',showFPS:false,spellRenderer:localStorage.getItem('pinball-spell-renderer')==='2d'?'2d':'webgl',effectsRenderer:localStorage.getItem('pinball-effects-renderer')==='2d'?'2d':'webgl',launchMode:localStorage.getItem('pinball-launch-mode')==='drag'?'drag':'hold'};}
  catch{return {language:PinballI18n.locale,sound:true,volume:1,playAspect:'portrait',physicsModel:'legacy',showFPS:false,spellRenderer:'webgl',effectsRenderer:'webgl',launchMode:'hold'};}
