  const loadingTitle=document.getElementById('loading-title'),loadingKey=praying?'loading.prayer':'loading.title';
  loadingTitle.setAttribute('data-i18n',loadingKey);loadingTitle.textContent=PinballI18n.t(loadingKey);
  tableLoading.hidden=!needsLoading;
